import{z as i,x as o,o as e,c as s,q as t,j as A,D as E,d as n,s as r,S as l}from"./chunks/framework.C8m1ZpeB.js";const _=JSON.parse('{"title":"可转债市场结构","description":"","frontmatter":{"title":"可转债市场结构","date":"2026-09-08T00:00:00.000Z","section":"quant"},"headers":[],"relativePath":"quant/cn-convertible-market.md","filePath":"quant/cn-convertible-market.md","lastUpdated":1791063341000}'),d={name:"quant/cn-convertible-market.md"};function p(C,a,c,h,D,m){const B=o("Mermaid");return e(),s("div",null,[a[2]||(a[2]=t('<h1 id="可转债市场结构" tabindex="-1">可转债市场结构 <a class="header-anchor" href="#可转债市场结构" aria-label="Permalink to &quot;可转债市场结构&quot;">​</a></h1><div class="epigraph"><p>A 股可转债是「债券 + 转股权 + 下修与赎回条款」在交易所竞价；T+0、涨跌停与正股 T+1 不对称，使联立对冲变成制度问题，而不只是模型 delta。</p><footer>—— 沪深交易所可转换公司债券交易规则与上市规则相关条款；Mitchell, Pedersen and Pulvino, Slow Moving Capital, AER, 2007；对照[可转债套利](/quant/convertible-arb)</footer></div><p><a href="/quant/cn-commodity-options">上一课</a>停在商品波动率。本课回到交易所信用–权益混合。<a href="/quant/convertible-arb">可转债套利</a> 已写 delta 对冲与慢资本；<a href="/quant/convertible-credit">转债信用</a> 写定价核。本课的缺口是<strong>A 股市场结构</strong>：竞价、涨跌停、转股、下修、强赎、与正股 T+1 / 融券约束如何改写可交易带。后课北交所换一层公司宇宙。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>国际转债套利假设正股可连续卖空、转债与正股同步交易。A 股：转债多数可当日回转，正股 T+1；正股涨跌停 10% 或 20%，转债涨跌停幅度不同（历史上与现行规则以交易所公告为准，回测须分段）；融券正股受标的与券源限制。于是「便宜凸性」可能无法对冲，或只能用期货对冲 beta，留下特异风险。问题是把可交易集写成：条款模型价 − 市价 − 对冲摩擦（涨跌停、T+1、借券、冲击）。摩擦大于折价则不是套利，是风险溢价或不可执行。</p><p><span class="marginnote">术语翻译：「强赎」是发行人的权利——正股涨得太好时，按面值加少量利息提前赎回转债，逼持有者转股或卖出；「下修」是发行人把转股价调低——正股跌得太深、持有人快有回售权时发生。一个在涨时省稀释，一个在跌时避还钱，两者都是发行人与持有人的条款博弈。</span></p><p>下修、强赎、回售是发行人与持有人的博弈，公告窗口伴随停牌，见<a href="/quant/cn-halt-resume">停复牌</a>。用连续 delta 对冲穿过停牌，路径非法。转股形成的股票仍受 T+1，当日转股当日卖出的可行性以规则为准，不得假设。</p><p><span class="marginnote">数字实例（常见条款示例，各券以募集说明书为准）：转股价 10 元，强赎触发常为「正股连续 30 个交易日中至少 15 日收盘不低于转股价的 130%」，即 13 元。触发并公告后，若不转股也不卖出，转债将被按约 100 元出头的面值加利息赎走——市价 140 元的转债立刻损失近 40 元，这就是强赎期限逼人行动的原因。</span></p>',8)),(e(),A(l,null,{default:E(()=>[r(B,{id:"mermaid-22",class:"mermaid",graph:"flowchart%20TD%0A%20%20DOWN%5B%22%E6%AD%A3%E8%82%A1%E6%8C%81%E7%BB%AD%E4%B8%8B%E8%B7%8C%22%5D%20--%3E%20TRG1%5B%22%E8%A7%A6%E5%8F%91%E4%B8%8B%E4%BF%AE%2F%E5%9B%9E%E5%94%AE%E6%9D%A1%E4%BB%B6%22%5D%0A%20%20TRG1%20--%3E%20REV%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E9%80%89%E6%8B%A9%EF%BC%9A%E4%B8%8B%E4%BF%AE%E8%BD%AC%E8%82%A1%E4%BB%B7%20%E6%88%96%20%E6%89%BF%E5%8F%97%E5%9B%9E%E5%94%AE%22%5D%0A%20%20REV%20--%3E%7C%22%E4%B8%8B%E4%BF%AE%22%7C%20FIX%5B%22%E8%BD%AC%E8%82%A1%E4%BB%B7%E8%B0%83%E4%BD%8E%EF%BC%8C%E6%9C%9F%E6%9D%83%E4%BB%B7%E5%80%BC%E9%87%8D%E4%BC%B0%22%5D%0A%20%20UP%5B%22%E6%AD%A3%E8%82%A1%E6%8C%81%E7%BB%AD%E4%B8%8A%E6%B6%A8%22%5D%20--%3E%20TRG2%5B%22%E8%A7%A6%E5%8F%91%E5%BC%BA%E8%B5%8E%E6%9D%A1%E4%BB%B6%EF%BC%88%E5%A6%82%E8%BD%AC%E8%82%A1%E4%BB%B7%20130%25%EF%BC%89%22%5D%0A%20%20TRG2%20--%3E%20CALL%5B%22%E5%8F%91%E8%A1%8C%E4%BA%BA%E5%85%AC%E5%91%8A%E6%8F%90%E5%89%8D%E8%B5%8E%E5%9B%9E%22%5D%0A%20%20CALL%20--%3E%20ACT%5B%22%E6%8C%81%E6%9C%89%E4%BA%BA%E9%A1%BB%E5%9C%A8%E6%9C%9F%E9%99%90%E5%86%85%E8%BD%AC%E8%82%A1%E6%88%96%E5%8D%96%E5%87%BA%22%5D%0A%20%20FIX%20--%3E%20GAME%5B%22%E6%9D%A1%E6%AC%BE%E5%8D%9A%E5%BC%88%E7%AA%97%E5%8F%A3%E4%BC%B4%E9%9A%8F%E5%81%9C%E7%89%8C%E4%B8%8E%E6%8B%A5%E6%8C%A4%22%5D%0A%20%20ACT%20--%3E%20GAME%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[n(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<h3 id="流动性与投资者结构" tabindex="-1">流动性与投资者结构 <a class="header-anchor" href="#流动性与投资者结构" aria-label="Permalink to &quot;流动性与投资者结构&quot;">​</a></h3><p>转债投资者含公募、私募、银行理财与散户，流动性在条款博弈日集中。平价附近换手高，深虚值更像信用债。容量按转债 ADV 与正股可空量的最小计。2017–2021 供给扩张与 2024 年监管与定价环境变化，使样本不可当成单一制度。</p><p><span class="marginnote">转债在交易所竞价，不是银行间信用债。估值用交易所成交，不要用中债估值去填可交易价。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>条款引擎：转股价、下修触发、赎回触发、回售、修正后转股价。市场数据：转债竞价、正股竞价、停牌与涨跌停状态。对冲：优先正股融券（若在可行集），否则行业期货或 ETF，并报告残差。回测在正股涨停时停止买入对冲腿、跌停时停止卖出，转债腿按自身停板。事件：下修/强赎公告日用公告时点，不用财报日。</p><p>与<a href="/quant/cn-public-quant">指增</a>：公募持有转债的比例与估值方法受产品规则约束，不能把对冲基金式杠杆转债套利写进公募指增。</p><h3 id="信用与权益因子拆开" tabindex="-1">信用与权益因子拆开 <a class="header-anchor" href="#信用与权益因子拆开" aria-label="Permalink to &quot;信用与权益因子拆开&quot;">​</a></h3><p>平价低时信用利差主导，应用信用研究方法；平价高时看权益波动与下修期权。混合样本的单一「转债因子」没有对象。Mitchell 等慢资本在 A 股对应：条款博弈日拥挤、融资与正股停牌使折价持续。</p><p><span class="marginnote">常见误区：初学者容易把深虚值转债当「便宜的股票看涨期权」继续调波动率参数。实际上平价很低时它更像一张信用债——价格由发行人的偿付能力与回售条款主导，正股再怎么反弹，违约风险不解除，转债也涨不动。研究方法要整段切换，而不是改参数。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>不对称交易规则制造结构性错误定价带：可以看见、不能锁。带的宽度随融券政策与涨跌停而变。2015 年正股跌停、转债仍交易（或相反，视当时规则），对冲缺口放大。这是微观结构，不是 BS 隐含波动「算错」。</p><p>转股稀释与下修改变有效行权价，路径依赖强。模型必须用当时有效转股价，点-in-time 条款与会计 vintage 同纪律。</p>',12)),(e(),A(l,null,{default:E(()=>[r(B,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20CB%5B%22%E8%BD%AC%E5%80%BA%E7%AB%9E%E4%BB%B7%20%E5%A4%9A%E5%8F%AF%20T%2B0%22%5D%20--%3E%20Spread%5B%22%E6%8A%98%E6%BA%A2%E4%BB%B7%22%5D%0A%20%20Eq%5B%22%E6%AD%A3%E8%82%A1%20T%2B1%20%E6%B6%A8%E8%B7%8C%E5%81%9C%22%5D%20--%3E%20Hedge%5B%22%E5%AF%B9%E5%86%B2%E5%8F%AF%E8%A1%8C%E9%9B%86%22%5D%0A%20%20Lend%5B%22%E8%9E%8D%E5%88%B8%E7%BA%A6%E6%9D%9F%22%5D%20--%3E%20Hedge%0A%20%20Hedge%20--%3E%20Exec%5B%22%E5%8F%AF%E6%89%A7%E8%A1%8C%E5%B8%A6%22%5D%0A%20%20Spread%20--%3E%20Exec%0A%20%20Call%5B%22%E5%BC%BA%E8%B5%8E%E4%B8%8B%E4%BF%AE%E5%81%9C%E7%89%8C%22%5D%20--%3E%20Exec%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[n(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不提供利用未公开下修信息、或在停牌规则边缘阻碍投资者交易的方法。可交换债、分离交易可转债条款不同。银行间转债极少，本课对象是交易所可转债。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>A 股转债的可交易带由 T+0/T+1 不对称、涨跌停与融券共同决定。</li><li>对冲残差必须报告；条款须点-in-time。</li><li>容量取转债流动性与正股可空的最小。</li><li>出处：沪深转债交易与上市规则；Mitchell, Pedersen and Pulvino, <em>AER</em>, 2007。</li></ul>',4))])}const T=i(d,[["render",p]]);export{_ as __pageData,T as default};
